 return `${titleBand('AKADEMİK KURUMLAR','Üniversiteler ve Programlar','Üniversite, doktora programı ve başvuru tarihlerini yönet.',btn(u.length?'Üniversite ekle':'İlk üniversiteyi ekle','add-university','plus','btn-primary'))}<div class="metrics-4">${metric('Toplam üniversite',u.length,'Kurum kayıtları','school')}${metric('Doktora programı',p.length,'Program seçenekleri','book')}${metric('Danışman',a.length,'İlişkili akademisyenler','users')}${metric('Yaklaşan tarih',p.filter(x=>x.deadline&&daysTo(x.deadline)>=0&&daysTo(x.deadline)<=30).length,'30 gün içinde','calendar')}</div>${sectionTiles([sectionTile('universities-list','Üniversite listesi',`${u.length} kayıt · Üniversite, ülke veya şehir ara`,'school')])}`;
