function universityDetail(id){let s=byId('universities',id);if(!s)return '';let ps=(state.cache.programs||[]).filter(x=>Number(x.university_id)===Number(id)),as=(state.cache.advisors||[]).filter(x=>Number(x.university_id)===Number(id));return `${sectionPageHead(s.name,[s.city,s.country].filter(Boolean).join(' · '))}<section class="premium-panel uni-detail">${blockHeading('Üniversite bilgileri','school',`<button class="btn btn-small" data-edit="universities" data-id="${s.id}">${icon('edit')} Düzenle</button>`)}<p class="detail-body">${esc(s.name)}</p><div class="detail-flag-row">${pill(s.ylsy_status)}<span class="pill">${ps.length} doktora programı</span><span class="pill">${as.length} danışman</span></div>${s.url?`<div class="fact-list"><div><b>Resmî site</b><span>${link(s.url,'Üniversite sayfasını aç')}</span></div></div>`:''}${s.note?`<div class="helper-note">${esc(s.note)}</div>`:''}<div class="section-divider"></div><div class="flex-title"><h3>Doktora programları</h3><button class="text-action" data-act="add-program">${icon('plus',14)} Program ekle</button></div>${ps.length?ps.map(x=>`<div class="related-item"><div><b>${esc(x.name)}</b><small>${esc(x.laboratory||'Laboratuvar girilmedi')} · Son tarih: ${fmtDate(x.deadline)}</small><small>${x.deadline_verified?'Tarih doğrulandı':'Tarih henüz doğrulanmadı'}</small></div><button class="round-btn" data-edit="programs" data-id="${x.id}">${icon('edit')}</button></div>`).join(''):'<p class="muted">Bu üniversite için henüz doktora programı kaydedilmedi.</p>'}<div class="section-divider"></div><div class="flex-title"><h3>Danışmanlar</h3><button class="text-action" data-act="add-advisor">${icon('plus',14)} Danışman ekle</button></div>${as.length?as.map(x=>`<div class="related-item"><div><b>${esc(x.name)}</b><small>${esc(truncate(x.topic,100))}</small></div>${pill(x.status)}</div>`).join(''):'<p class="muted">Bu üniversiteye bağlı danışman bulunmuyor.</p>'}<div class="detail-actions margin-top">${btn('Üniversiteyi sil','delete-university','trash','btn-danger')}</div></section>`;
}
function advisors(){const list=state.cache.advisors||[];if(!list.some(x=>Number(x.id)===Number(state.selectedAdvisor)))state.selectedAdvisor=list[0]?.id||null;const chosen=byId('advisors',state.selectedAdvisor),u=byId('universities',chosen?.university_id);
 if(state.subpage==='advisors-list')return `${sectionPageHead('Danışman listesi','Danışman adı veya araştırma alanına göre ara.') }<section class="premium-panel list-with-filter"><div class="filter-line">${icon('search')}<input class="inline-search" placeholder="Danışman veya araştırma alanı ara..." data-live-filter aria-label="Danışmanlarda ara"/></div><div class="advisors-list">${list.length?list.map(x=>{const school=byId('universities',x.university_id);return `<button class="uni-row" data-act="select-advisor" data-id="${x.id}" data-match="${attr([x.name,school?.name,x.university,x.topic,x.status].join(' '))}"><span class="uni-glyph">${icon('users',23)}</span><span class="uni-info"><strong>${esc(x.name)}</strong><small>${esc(school?.name||x.university)}</small><small>${esc(truncate(x.topic,100))}</small></span>${icon('right')}</button>`}).join(''):empty('Henüz danışman eklenmedi','Danışman listene ilk kaydını ekle.','add-advisor','İlk danışmanı ekle')}</div></section>`;
 if(state.subpage==='advisor-detail'&&chosen)return `${sectionPageHead(chosen.name,u?.name||chosen.university)}<section class="premium-panel uni-detail"><div class="block-heading"><h2>${icon('users',21)} ${esc(chosen.name)}</h2><button class="btn btn-small" data-edit="advisors" data-id="${chosen.id}">${icon('edit')} Düzenle</button></div><p class="detail-body">${esc(u?.name||chosen.university)} · ${esc(chosen.topic||'Araştırma alanı belirtilmedi')}</p><div class="detail-flag-row">${pill(chosen.status)}${chosen.last_contact?`<span class="pill">Son temas: ${fmtDate(chosen.last_contact)}</span>`:''}</div><div class="fact-list"><div><b>Üniversite</b><span>${esc(u?.name||chosen.university||'—')}</span></div><div><b>Kurumsal e-posta</b><span>${chosen.email?`<a href="mailto:${attr(chosen.email)}">${esc(chosen.email)}</a>`:'Belirtilmedi'}</span></div>${u?.url?`<div><b>Üniversite sitesi</b><span>${link(u.url,'Resmî sayfayı aç')}</span></div>`:''}</div><div class="detail-actions">${link(chosen.url,'Akademisyen sayfası')}${btn('E-posta taslağı oluştur','advisor-email','file','btn-primary')}</div><h3 class="subsection-heading">Araştırma ve yayın notları</h3>${chosen.note?`<p class="detail-body multiline">${esc(chosen.note)}</p>`:'<p class="muted">Henüz yayın veya görüşme notu yok.</p>'}</section>`;
 return `${titleBand('ARAŞTIRMA VE İLETİŞİM','Danışmanlar ve Laboratuvarlar','Danışman bilgilerini ve iletişim geçmişini yönet.',btn(list.length?'Danışman ekle':'İlk danışmanı ekle','add-advisor','plus','btn-primary'))}${sectionTiles([sectionTile('advisors-list','Danışman listesi',`${list.length} kayıt · Danışman veya araştırma alanı ara`,'users')])}`;
}
function applications(){const p=state.cache.programs||[];const cols=[['Araştırılıyor',['Araştırılıyor','Danışman iletişimi']],['Hazırlanıyor',['Başvuru hazırlanıyor']],['Gönderildi',['Başvuru gönderildi']],['Sonuç bekleniyor',['Bekleme listesi']],['Sonuçlandı',['Kabul','Ret','Vazgeçildi']]];
 const board=()=>`${sectionPageHead('Başvuru panosu','Doktora programlarının mevcut başvuru aşamaları.') }${!p.length?`<section class="premium-panel first-empty">${empty('Başvuru panosu boş','Önce bir üniversite doktora programı ekle; ardından başvuru aşamalarını burada yönetebilirsin.','add-program','İlk programı ekle')}</section>`:`<div class="kanban-board">${cols.map(([c,st])=>{const items=p.filter(x=>st.includes(x.stage));return `<section class="kanban-column"><header>${esc(c)} <span>${items.length}</span></header>${items.map(x=>`<div class="kanban-card"><strong>${esc(x.university)}</strong><p>${esc(x.name)}</p><small>Son tarih: ${fmtDate(x.deadline)} ${x.deadline_verified?'· Doğrulandı':'· Doğrulanmadı'}</small>${pill(x.stage)}<div class="head-actions"><button class="btn btn-small" data-edit="programs" data-id="${x.id}">${icon('edit')} Düzenle</button></div></div>`).join('')||'<p class="kanban-empty">Bu aşamada kayıt yok</p>'}</section>`}).join('')}</div>`}`;
 if(state.subpage==='applications-board')return board();
 return `${titleBand('DOKTORA PROGRAMLARI','Başvuru Yönetimi','Program ekle, başvuru takibini ayrı panoda yönet.',btn(p.length?'Program ekle':'İlk programı ekle','add-program','plus','btn-primary'))}<div class="metrics-4">${metric('Toplam program',p.length,'Kayıtlı seçenekler','school')}${metric('Hazırlanan',p.filter(x=>x.stage==='Başvuru hazırlanıyor').length,'Başvuru dosyaları','file')}${metric('Gönderilen',p.filter(x=>x.stage==='Başvuru gönderildi').length,'Başvurular','briefcase')}${metric('Kabul',p.filter(x=>x.stage==='Kabul').length,'Olumlu sonuçlar','check')}</div>${sectionTiles([sectionTile('applications-board','Başvuru panosu',p.length?`${p.length} programın aşamalarını görüntüle`:'Henüz program eklenmedi','briefcase')])}`;
}
function templateShelf(){return `<div class="doc-catalog-tools"><div class="doc-search filter-line">${icon('search')}<input class="inline-search" aria-label="Şablonlarda ara" placeholder="Şablon adı veya rehber eki ara…" data-live-filter></div><span class="doc-result-count">${state.templates.length} şablon</span></div><div class="template-list">${state.templates.map((t,i)=>`<article class="template-item" data-match="${attr([t.title,t.ref_key,t.kind].join(' '))}"><div class="template-main"><span class="template-mark">${icon('file',18)}</span><div class="template-copy"><strong>${esc(t.title)}</strong><small>${esc(t.kind||'Belge taslağı')} <i>·</i> Rehber ${esc(t.ref_key)} <i>·</i> PDF s. ${t.page}</small></div></div><div class="template-actions"><button class="btn btn-small" data-act="preview-template" data-index="${i}">${icon('search',14)} Ön izle</button><button class="btn btn-small btn-primary" data-act="create-template" data-index="${i}">${icon('plus',14)} Kullan</button></div></article>`).join('')}<p class="doc-filter-empty" data-filter-empty hidden>Bu aramayla eşleşen şablon bulunamadı.</p></div>`}
function docSectionPageHead(title,subtitle=''){return `<div class="section-page-head doc-section-page-head"><button class="section-back" data-act="back-subpage" aria-label="Geri">${icon('left',18)}<span>Geri</span></button><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div></div>`}
function previewTemplate(i){if(!state.templates[i])return;state.templatePreviewIndex=i;return openSubpage('documents-template-preview')}
function documentHeaderActions(){return state.docFocus?btn('Belgelerime dön','doc-back','left'):btn(docs.length?'Yeni belge':'İlk belgeyi oluştur','add-document','plus','btn-primary')+btn('Şablonlar','choose-template','book')}
function documents(){const docs=state.cache.documents||[],chosen=byId('documents',state.docId),t=state.templates;
 if(state.docFocus&&chosen)return `${docSectionPageHead(chosen.title,chosen.kind)}<section class="premium-panel doc-editor-panel"><header class="editor-header"><div><h2>${esc(chosen.title)}</h2><p>${esc(chosen.kind)} · Cihazına otomatik kaydedilir</p></div><div class="editor-header-actions"><button class="btn btn-small" data-act="doc-export" data-id="${chosen.id}">${icon('download')} DOCX</button><button class="btn btn-small" data-edit="documents" data-id="${chosen.id}">${icon('edit')} Düzenle</button></div></header><div class="editor-tools"><button class="btn btn-small" data-act="format-doc" data-command="bold"><b>Kalın</b></button><button class="btn btn-small" data-act="format-doc" data-command="italic"><i>İtalik</i></button><button class="btn btn-small" data-act="format-doc" data-command="insertUnorderedList">${icon('task')} Liste</button><button class="btn btn-small" data-act="save-doc">${icon('save')} Kaydet</button><small class="muted" id="save-indicator">Tüm değişiklikler kaydedildi</small></div><div class="doc-paper-scroll"><div class="editor-body" contenteditable="true" role="textbox" aria-label="Belge düzenleyici" id="doc-editor" data-document-id="${chosen.id}">${cleanHtml(chosen.html)}</div></div>${chosen.source_page?`<div class="editor-footer"><button class="inline-link" data-act="pdf-page" data-page="${chosen.source_page}">MEB rehberi · PDF sayfa ${chosen.source_page} ${icon('external',14)}</button></div>`:''}<div class="doc-bottom-actions"><div>${btn('Belgelerime dön','doc-back','left')}</div><button type="button" class="btn btn-danger" data-act="delete-selected-document">${icon('trash')} Belgeyi sil</button></div></section>`;
 if(state.subpage==='documents-templates')return `${docSectionPageHead('Şablonlar','Bir şablonu ön izle veya yeni belge oluştur.') }<section class="premium-panel list-with-filter">${templateShelf()}</section>`;
 if(state.subpage==='documents-template-preview'){const x=t[state.templatePreviewIndex];if(!x){state.subpage='documents-templates';return documents()}return `${docSectionPageHead(x.title,`${x.kind||'Belge taslağı'} · Rehber ${x.ref_key} · PDF s. ${x.page}`)}<section class="premium-panel doc-preview-page"><div class="doc-preview-note">Bu taslak düzenlenebilir bir başlangıç belgesidir. Oluşturduktan sonra kendi bilgilerine göre düzenleyebilirsin.</div><article class="template-preview">${cleanHtml(x.html)}</article><div class="doc-preview-actions"><button class="btn" data-act="pdf-open-page" data-page="${x.page}">${icon('book')} Rehberdeki örnek</button><button class="btn btn-primary" data-act="create-template" data-index="${state.templatePreviewIndex}">${icon('plus')} Bu şablonla oluştur</button></div></section>`}
 if(state.subpage==='documents-list')return `${docSectionPageHead('Belgelerim','Kaydettiğin belgeler burada; açmak için belgeye dokun.') }<section class="premium-panel doc-list-page list-with-filter"><div class="doc-catalog-tools"><div class="doc-search filter-line">${icon('search')}<input class="inline-search" aria-label="Belgelerimde ara" placeholder="Belge adı veya türüne göre ara…" data-live-filter></div><span class="doc-result-count">${docs.length} belge</span></div><div class="doc-list">${docs.length?docs.map(x=>`<button class="doc-list-item document-page-item" data-act="doc-select" data-id="${x.id}" data-match="${attr([x.title,x.kind,x.updated_at].join(' '))}"><span class="doc-row-icon">${icon('file',19)}</span><span class="doc-row-copy"><b>${esc(x.title)}</b><small>${esc(x.kind)} <i>·</i> Güncellendi ${esc(x.updated_at?.slice(0,10)||'')}</small></span><span class="doc-open-label">Aç</span>${icon('right',14)}</button>`).join('')+`<p class="doc-filter-empty" data-filter-empty hidden>Bu aramayla eşleşen belge bulunamadı.</p>`:empty('Henüz kişisel belge yok','Şablonlardan birini kullanarak ilk belgeni oluştur.','choose-template','Şablonlara göz at')}</div></section>`;
 return `<div class="doc-studio-home">${titleBand('BELGE ÇALIŞMA ALANI','Belge Stüdyosu','Başvuru belgelerini hazırla, şablondan oluştur ve kayıtlarını tek yerde yönet.',`${btn(docs.length?'Yeni belge':'İlk belgeyi oluştur','add-document','plus','btn-primary')}<button type="button" class="btn doc-templates-cta" data-act="open-subpage" data-subpage="documents-templates">${icon('book')} Şablonlara göz at</button>`)}<div class="doc-studio-summary"><div><span class="doc-summary-icon">${icon('book',19)}</span><span><b>${t.length} hazır şablon</b><small>MEB rehberine dayalı düzenlenebilir taslaklar</small></span></div><div><span class="doc-summary-icon">${icon('file',19)}</span><span><b>${docs.length} kişisel belge</b><small>Son değişiklikler otomatik kaydedilir</small></span></div></div><div class="doc-home-links"><button class="doc-home-link" data-act="open-subpage" data-subpage="documents-templates"><span class="doc-home-icon">${icon('book',21)}</span><span><b>Şablon kütüphanesi</b><small>Ön izle, ara ve yeni belge oluştur</small></span>${icon('right',17)}</button><button class="doc-home-link" data-act="open-subpage" data-subpage="documents-list"><span class="doc-home-icon">${icon('file',21)}</span><span><b>Belgelerim</b><small>Oluşturduğun belgeleri açıp düzenle</small></span>${icon('right',17)}</button></div></div>`;
}
function ielts(){const all=state.cache.ielts_sessions||[],mins=all.reduce((s,x)=>s+(Number(x.minutes)||0),0),now=new Date(),period=state.ieltsPeriod||'all',skill=state.ieltsSkill||'all',sort=state.ieltsSort||'newest';let rows=all.filter(x=>skill==='all'||x.skill===skill).filter(x=>{if(period==='all')return true;const d=new Date(String(x.date||'')+'T00:00:00'),days=(now-d)/86400000;if(Number.isNaN(d.getTime()))return false;return period==='day'?days>=0&&days<1:period==='week'?days>=0&&days<7:period==='month'?d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear():period==='year'?d.getFullYear()===now.getFullYear():true});rows.sort((x,y)=>sort==='oldest'?String(x.date).localeCompare(String(y.date)):String(y.date).localeCompare(String(x.date)));const skills=['Listening','Reading','Writing','Speaking'],icons=['language','book','edit','users'];
 if(state.subpage==='ielts-skills')return `${sectionPageHead('Beceri özeti','Her beceri için kaydedilen çalışma süresi ve oturum sayısı.') }<div class="skill-grid">${skills.map((sk,i)=>{let arr=all.filter(x=>x.skill===sk),m=arr.reduce((v,x)=>v+Number(x.minutes||0),0);return `<div class="skill-card">${icon(icons[i])}<h3>${sk}</h3><b>${(m/60).toFixed(1)} saat</b><small>${arr.length} oturum</small></div>`}).join('')}</div>`;
 if(state.subpage==='ielts-history')return `${sectionPageHead('Çalışma geçmişi','Beceri, tarih sırası ve dönem filtresiyle çalışmalarını bul.') }<section class="premium-panel"><div class="ielts-filters"><label>Beceri<select data-act="ielts-filter-skill"><option value="all">Tüm beceriler</option>${['Listening','Reading','Writing','Speaking','Grammar','Vocabulary','Academic English','Mock Test'].map(v=>`<option value="${v}" ${skill===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Sıralama<select data-act="ielts-filter-sort"><option value="newest" ${sort==='newest'?'selected':''}>Yeniden eskiye</option><option value="oldest" ${sort==='oldest'?'selected':''}>Eskiden yeniye</option></select></label><label>Dönem<select data-act="ielts-filter-period"><option value="all">Tüm zamanlar</option><option value="day" ${period==='day'?'selected':''}>Bugün</option><option value="week" ${period==='week'?'selected':''}>Bu hafta</option><option value="month" ${period==='month'?'selected':''}>Bu ay</option><option value="year" ${period==='year'?'selected':''}>Bu yıl</option></select></label></div>${rows.length?rows.map(x=>`<div class="related-item"><div><b>${esc(x.skill)} · ${Number(x.minutes)} dakika</b><small>${fmtDate(x.date)} ${x.score?' · Puan: '+esc(x.score):''}</small>${x.note?`<small>${esc(truncate(x.note,120))}</small>`:''}</div><div class="list-row-actions"><button class="round-btn" data-delete="ielts_sessions" data-id="${x.id}" title="Sil">${icon('trash')}</button><button class="round-btn" data-edit="ielts_sessions" data-id="${x.id}" title="Düzenle">${icon('edit')}</button></div></div>`).join(''):empty('Bu seçimde çalışma yok','Filtreleri değiştir veya yeni bir oturum kaydet.','add-ielts',all.length?'Çalışma ekle':'İlk çalışmayı ekle')}</section>`;
 if(state.subpage==='ielts-targets')return `${sectionPageHead('Dil hedefleri','İngilizce seviyeni ve IELTS hedef puanını belirle.') }<section class="premium-panel"><div class="field"><label for="cefr">Mevcut İngilizce seviyen</label><select id="cefr" class="form-control"><option value="">Belirlenmedi</option>${['A1','A2','A2+','B1','B1+','B2','C1','C2'].map(x=>`<option ${x===state.settings.cefr?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="target">IELTS Academic hedef puanın</label><input class="form-control" id="target" value="${attr(state.settings.ielts_target||'')}" placeholder="Örn. 7.0"/></div><div class="field"><label for="course-end">Dil eğitimi bitiş tarihi</label><input id="course-end" class="form-control" type="date" value="${attr(state.settings.course_end||'')}"/></div>${btn('Hedefleri kaydet','save-ielts-settings','save','btn-primary')}<div class="section-divider"></div><p class="detail-body">Dil puanı koşullarını hedef üniversitenin resmî program sayfasından doğrula.</p></section>`;
 return `${titleBand('İNGİLİZCE HAZIRLIK','IELTS ve Dil Gelişimi','Çalışma, hedef ve kelime çalışmalarını aynı alandan yönet.',`${btn('AI çalışma koçu','open-ai-coach','sparkle')}${btn(all.length?'Çalışma ekle':'İlk çalışmayı ekle','add-ielts','plus','btn-primary')}`)}${sectionTiles([sectionTile('ielts-skills','Beceri özeti','Listening, Reading, Writing ve Speaking','chart'),sectionTile('ielts-history','Çalışma geçmişi',`${all.length} kayıt · ${(mins/60).toFixed(1)} toplam saat`,'calendar'),sectionTile('ielts-targets','Dil hedefleri',`${state.settings.cefr||'Seviye belirlenmedi'} · IELTS ${state.settings.ielts_target||'hedef belirlenmedi'}`,'flag'),`<button type="button" class="section-tile" data-act="goto-vocabulary"><span class="section-tile-icon">${icon('book',23)}</span><span class="section-tile-copy"><strong>Kelime defteri</strong><small>${(state.cache.vocabulary||[]).length} kelime · kelime çalışması ve quiz</small></span>${icon('right',18)}</button>`])}`;
}
function eligibilityView(){const f=state.eligibilityForm,u=state.cache.universities||[],selectedId=f.universityId||(u.length===1?String(u[0].id):''),chosen=u.find(x=>String(x.id)===String(selectedId)),r=state.eligibilityResult;const labels={likely_eligible:'Ölçütlere uygun görünüyor',not_eligible:'Belirtilen ölçütü karşılamıyor',insufficient_evidence:'Kanıt yetersiz'};return `${titleBand('KAYNAKLI ÖN DEĞERLENDİRME','YLSY Uygunluk Kontrolü','Kayıtlı üniversiteni seç; doktora alanını ve başvuru yılını belirt, güncel resmî koşullar kaynaklarıyla araştırılsın.')}
 <section class="eligibility-panel"><p class="eligibility-intro">“İlk 500” her yıl uygulanan sabit bir kural değildir. MEB ölçütünü seçtiğin başvuru yılına ve doktora alanına göre araştırıyorum.</p>${u.length?`<div class="eligibility-form">
 <label class="field eligibility-wide" for="eligibility-university"><span>Kayıtlı üniversite</span><select id="eligibility-university" class="form-control" data-act="eligibility-university-select"><option value="">Üniversite seçin</option>${u.map(x=>`<option value="${attr(x.id)}" ${String(x.id)===String(selectedId)?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${chosen?`<small class="eligibility-university-meta">${esc([chosen.city,chosen.country].filter(Boolean).join(' · ')||'Konum belirtilmedi')}${chosen.url?' · Resmî site kayıtlı':''}</small>`:''}</label>
 <label class="field"><span>Doktora alanı</span><input id="eligibility-field" class="form-control" placeholder="Örn. Makine Mühendisliği" value="${attr(f.field)}"><small class="eligibility-university-meta">Üniversitede başvurmayı düşündüğün bölüm veya araştırma alanı.</small></label>
 <label class="field"><span>YLSY başvuru yılı</span><input id="eligibility-cycle" class="form-control" inputmode="numeric" placeholder="Örn. 2025" value="${attr(f.cycle)}"></label>
 </div><button class="btn btn-primary eligibility-submit" data-act="check-eligibility" ${state.eligibilityBusy||!chosen?'disabled':''}>${icon(state.eligibilityBusy?'clock':'search')} ${state.eligibilityBusy?'Resmî kaynaklar araştırılıyor…':'Kaynakları araştır ve değerlendir'}</button>`:`<p class="eligibility-intro">Önce Üniversiteler bölümünden değerlendirmek istediğin üniversiteyi ekle. Üniversite adı ve kayıtlı konum bilgisi değerlendirmeye otomatik aktarılır.</p>${btn('Üniversite ekle','eligibility-add-university','plus','btn-primary')}`}
 ${!state.aiStatus?.configured?`<p class="eligibility-key-note">Kaynaklı AI araştırması için Gemini API anahtarı gerekir. Uygulama anahtarını bu cihazda güvenli tutar. <button class="text-action" data-act="eligibility-add-key">AI ayarlarını aç</button></p>`:''}</section>
 ${r?`<section class="eligibility-result"><div class="eligibility-result-head"><span class="eyebrow">${esc(r.cycle)} · ${esc(r.field)}</span><h2>${esc(labels[r.status]||labels.insufficient_evidence)}</h2><p>${esc(r.summary)}</p>${r.official_name?`<p class="eligibility-identity"><b>Eşleşen resmî ad:</b> ${esc(r.official_name)}${r.identity_note?' · '+esc(r.identity_note):''}</p>`:''}</div><div class="eligibility-finding"><h3>Uygulanan YLSY koşulu</h3><p>${esc(r.rule)}</p></div><div class="eligibility-finding"><h3>Üniversite sıralama kanıtı</h3><p>${esc(r.ranking_evidence)}</p></div>${r.cautions?.length?`<div class="eligibility-finding"><h3>Dikkat edilmesi gerekenler</h3><ul>${r.cautions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="eligibility-finding"><h3>Kaynaklar</h3><ol class="eligibility-sources">${(r.sources||[]).map(x=>`<li><b>${esc(x.title)}</b>${x.why?`<span>${esc(x.why)}</span>`:''}<div>${link(x.url,'Kaynağı aç')}</div></li>`).join('')||'<li>Doğrulanabilir kaynak bulunamadı.</li>'}</ol></div><p class="eligibility-disclaimer">Bu, kaynaklara dayalı ön değerlendirmedir; kesin uygunluk ve kabul kararı ilgili yılın MEB kılavuzu ve yetkili kurumlarındır.</p></section>`:''}`}
async function checkEligibility(){if(state.aiStatus?.unavailable)return toast('AI uygunluk değerlendirmesi bu masaüstü backendinde bulunmuyor.',true);const u=byId('universities',$('#eligibility-university')?.value);if(!u)return toast('Kayıtlı üniversitelerden birini seçin.',true);state.eligibilityForm={universityId:String(u.id),university:u.name,country:u.country||'',city:u.city||'',url:u.url||'',field:$('#eligibility-field')?.value.trim()||'',cycle:$('#eligibility-cycle')?.value.trim()||''};state.eligibilityBusy=true;render();try{state.eligibilityResult=await api('ai/eligibility','POST',state.eligibilityForm)}catch(e){toast(e.message,true)}finally{state.eligibilityBusy=false;render()}}
function administration(){let list=(state.cache.tasks||[]).filter(x=>['YLSY','Pasaport'].includes(x.track));return `${heading('Bursiyerlik & idari işlemler','YLSY & Pasaport','REBUS, resmî öğrenime başlama süreleri, pasaport ve vize hazırlığını kendi görevlerinle takip et.',btn(list.length?'İdari görev ekle':'İlk idari görevi ekle','add-admin-task','plus','btn-primary'))}<div class="grid2">${card('YLSY işlemleri',`<div class="helper-note">Öğrenime başlama süresi ve ülke/alan uygunluğu bursiyerliğinle ilgili resmî MEB belgelerinden teyit edilmelidir. Bu uygulama idari onay vermez.</div><div class="margin-top">${btn('REBUS’u aç','open-rebus','external')}</div>`)}${card('Pasaport ve vize',`<div class="helper-note">Pasaport başvurusu ve vize süreci farklı aşamalardır. ABD vize formları kabul ve ilgili üniversite belgeleri sonrası tamamlanır.</div><div class="margin-top">${btn('Pasaport randevu sitesi','open-nvi','external')}</div>`)}</div><div class="margin-top">${card('İdari görevlerim',list.length?list.map(taskRow).join(''):empty('İdari görev yok','Örneğin MEB teyidi, REBUS, pasaport randevusu gibi işleri kendi gerçek durumuna göre kaydet.','add-admin-task','İlk idari görevi ekle'))}</div>`}
function vocabularyQuiz(){const quiz=state.vocabQuiz;if(!quiz)return '';const words=state.cache.vocabulary||[];if(quiz.index>=quiz.ids.length)return `<section class="premium-panel vocab-quiz-result"><div class="vocab-quiz-icon">${icon('sparkle',30)}</div><h2>Quiz tamamlandı</h2><p>${quiz.known} / ${quiz.ids.length} kelimeyi hatırladın.</p><div class="title-actions">${btn('Yeniden başla','start-vocab-quiz','refresh')}${btn('Kelime listesine dön','stop-vocab-quiz','left')}</div></section>`;const word=words.find(x=>+x.id===+quiz.ids[quiz.index]);if(!word)return '';return `<section class="premium-panel vocab-quiz"><div class="vocab-quiz-top"><span class="eyebrow">KELİME QUIZİ</span><span class="pill">${quiz.index+1} / ${quiz.ids.length}</span></div><h2>${esc(word.word)}</h2><p>Bu kelimenin anlamı nedir?</p>${quiz.revealed?`<div class="vocab-answer"><strong>${esc(word.meaning)}</strong>${word.example?`<p>${esc(word.example)}</p>`:''}${word.note?`<small>${esc(word.note)}</small>`:''}</div><div class="vocab-quiz-actions"><button class="btn btn-danger" data-act="vocab-rate" data-known="false">Tekrar et</button><button class="btn btn-primary" data-act="vocab-rate" data-known="true">Hatırladım</button></div>`:`<button class="btn btn-primary" data-act="vocab-reveal">Cevabı göster</button>`}</section>`}
function vocabulary(){const all=state.cache.vocabulary||[],known=all.reduce((n,x)=>n+Number(x.known_count||0),0),reviews=all.reduce((n,x)=>n+Number(x.review_count||0),0);
 if(state.vocabDetailId){const word=byId('vocabulary',state.vocabDetailId);if(word)return vocabularyDetailView(word);state.vocabDetailId=null}
 if(state.subpage==='vocabulary-progress')return `${sectionPageHead('Kelime çalışma özeti','Kelimelerin, tekrarların ve hatırlama sonuçlarının özeti.') }<div class="metrics-3">${metric('Kelime sayısı',all.length,'Kişisel defterindeki kayıtlar','book')}${metric('Quiz tekrarları',reviews,'Toplam hatırlama denemesi','refresh')}${metric('Hatırlanan cevaplar',known,'Quizde “Hatırladım” işaretlediklerin','check')}</div>`;
 if(state.subpage==='vocabulary-list'){let words=all.slice();if(state.vocabSort==='alpha')words.sort((a,b)=>a.word.localeCompare(b.word,'en',{sensitivity:'base'}));else if(state.vocabSort==='alpha-desc')words.sort((a,b)=>b.word.localeCompare(a.word,'en',{sensitivity:'base'}));else if(state.vocabSort==='oldest')words.sort((a,b)=>a.created_at.localeCompare(b.created_at));else if(state.vocabSort==='review')words.sort((a,b)=>Number(a.review_count||0)-Number(b.review_count||0)||b.created_at.localeCompare(a.created_at));else words.sort((a,b)=>b.created_at.localeCompare(a.created_at));const rows=words.map(x=>`<article class="vocab-row" data-match="${attr([x.word,x.meaning,x.example].join(' '))}"><div class="vocab-word-main"><div class="vocab-word-title"><h3>${esc(x.word)}</h3></div><p class="vocab-meaning multiline">${esc(x.meaning)}</p></div><div class="list-row-actions"><button class="round-btn" data-edit="vocabulary" data-id="${x.id}" title="Düzenle">${icon('edit')}</button><button class="round-btn" data-delete="vocabulary" data-id="${x.id}" title="Sil">${icon('trash')}</button></div></article>`).join('');return `${sectionPageHead('Kelime listesi',`${all.length} kayıt · Bir karta dokunarak anlam ve örnekleri aç.`)}<section class="premium-panel vocab-library"><div class="vocab-toolbar"><div class="field vocab-search"><label for="vocab-search">Kelime veya anlam ara</label><input id="vocab-search" class="form-control" type="search" placeholder="Örn. resilience, dayanıklılık…" data-live-filter/></div><div class="field vocab-sort"><label for="vocab-sort">Sıralama</label><select id="vocab-sort" class="form-control" data-act="vocab-sort"><option value="newest" ${state.vocabSort==='newest'?'selected':''}>En son eklenen</option><option value="oldest" ${state.vocabSort==='oldest'?'selected':''}>En eski eklenen</option><option value="alpha" ${state.vocabSort==='alpha'?'selected':''}>Alfabetik (A–Z)</option><option value="alpha-desc" ${state.vocabSort==='alpha-desc'?'selected':''}>Alfabetik (Z–A)</option><option value="review" ${state.vocabSort==='review'?'selected':''}>Önce az çalışılanlar</option></select></div></div><div class="vocab-list">${rows||empty('Kelime defterin henüz boş','İngilizce kelime ekleyerek başlayabilirsin.','add-vocabulary','İlk kelimeyi ekle')}</div></section>`}
 if(state.subpage==='vocabulary-quiz')return `${sectionPageHead('Kelime quiz’i','Kendini sınamak için cevabı göster, ardından hatırlama durumunu işaretle.')}${vocabularyQuiz()||empty('Quiz hazır değil','Önce kelime defterine birkaç kelime ekle.','add-vocabulary','İlk kelimeyi ekle')}`;
 return `${titleBand('KİŞİSEL KELİME ÇALIŞMASI','Kelime Defterim','Kelime ekle, quiz başlat ve listeyi ayrı sayfalarda kullan.',`${btn(all.length?'Kelime ekle':'İlk kelimeyi ekle','add-vocabulary','plus','btn-primary')}${btn('Quiz başlat','start-vocab-quiz','sparkle')}`)}${sectionTiles([sectionTile('vocabulary-progress','Çalışma özeti',`${all.length} kelime · ${reviews} tekrar`,'chart'),sectionTile('vocabulary-list','Kelime listesi','Anlamları görüntüle, kelime kartından örneklere geç','book')])}`;
}

function upcoming(){let dates=[...(state.cache.events||[]).map(x=>({date:x.date,title:x.title,note:x.kind,kind:'event',id:x.id})),...(state.cache.programs||[]).filter(x=>x.deadline).map(x=>({date:x.deadline,title:x.university+' · '+x.name,note:x.deadline_verified?'Başvuru tarihi · doğrulandı':'Başvuru tarihi · doğrulanmadı',kind:'program',id:x.id})),...(state.cache.tasks||[]).filter(x=>x.due_date&&x.status!=='done').map(x=>({date:x.due_date,title:x.title,note:'Görev',kind:'task',id:x.id}))];return dates.sort((a,b)=>String(a.date).localeCompare(String(b.date)))}
function dateRow(x){return `<div class="date-item"><div class="date-pill"><b>${esc(String(x.date||'').slice(8,10))}</b><span>${esc(String(x.date||'').slice(0,7))}</span></div><div class="grow"><b style="font-size:12px">${esc(x.title)}</b><div class="tiny muted" style="margin-top:4px">${esc(x.note)}</div></div></div>`}
function calendar(){const events=upcoming(),now=new Date(),shownMonth=new Date(now.getFullYear(),now.getMonth()+(state.monthOffset||0),1),year=shownMonth.getFullYear(),month=shownMonth.getMonth();
 const first=(shownMonth.getDay()+6)%7,count=new Date(year,month+1,0).getDate();const cells=[];
 for(let c=0;c<Math.ceil((first+count)/7)*7;c++){const day=c-first+1;if(day<1||day>count){cells.push('<div class="cal-day muted-day"></div>');continue}const key=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const dayEvents=events.filter(e=>e.date===key);cells.push(`<div class="cal-day ${key===new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0')?'today':''}"><span>${day}</span>${dayEvents.slice(0,3).map(e=>`<span class="event-dot" title="${attr(e.title)}"></span>`).join('')}${dayEvents.length>3?`<small>+${dayEvents.length-3}</small>`:''}</div>`)}
 return `${titleBand('ZAMAN VE PLANLAMA','Takvim ve Hatırlatmalar','Son başvuru tarihleri, kişisel görevler, sınavlar ve etkinlikler tek takvimde.',btn((state.cache.events||[]).length?'Etkinlik ekle':'İlk etkinliği ekle','add-event','plus','btn-primary'))}
 <div class="calendar-layout"><section class="premium-panel"><div class="flex-title"><h2>${new Intl.DateTimeFormat('tr-TR',{month:'long',year:'numeric'}).format(shownMonth)}</h2><div class="cal-arrows"><button class="round-btn" data-act="calendar-prev" title="Önceki ay">${icon('left')}</button><button class="round-btn" data-act="calendar-today" title="Bu ay">Bugün</button><button class="round-btn" data-act="calendar-next" title="Sonraki ay">${icon('right')}</button></div></div><div class="calendar-grid">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(x=>`<div class="cal-weekday">${x}</div>`).join('')}${cells.join('')}</div><div class="legend"><span><i></i> En az bir kayıtlı etkinlik</span><span>Kaynak teyidi gereken tarihler, program sayfasında ayrıca işaretlenir.</span></div></section><section class="premium-panel">${blockHeading('Yaklaşan Etkinlikler','calendar')}<div class="calendar-events">${events.length?events.map(x=>`<div class="calendar-event">${dateRow(x)}${x.kind==='event'?`<button class="round-btn" data-edit="events" data-id="${x.id}">${icon('edit')}</button>`:''}</div>`).join(''):empty('Henüz bir etkinlik yok','Başvurular, görevler ve eklediğin etkinlikler burada listelenir.')}</div></section></div>`;
}
function files(){let a=state.cache.attachments||[];return `${heading('Yerel belge arşivi','Dosya Kasası','PDF ve diğer dosyaları uygulamaya ekleyip yerel cihazında sakla. Dosyalar buluta gönderilmez.',btn(a.length?'Dosya ekle':'İlk dosyayı ekle','upload-file','plus','btn-primary'))}${card('Dosyalarım',a.length?a.map(x=>`<div class="list-row"><div class="list-icon">${icon('paperclip')}</div><div class="list-row-main"><strong>${esc(x.original_name)}</strong><small>${(x.size/1024).toFixed(1)} KB · ${esc(x.owner_type)} · ${esc(x.updated_at?.slice(0,10)||'')}</small></div><div class="list-row-actions"><button class="round-btn" data-act="open-file" data-id="${x.id}" title="Dosyayı aç">${icon('external')}</button><button class="round-btn" data-act="delete-file" data-id="${x.id}" title="Sil">${icon('trash')}</button></div></div>`).join(''):empty('Dosya kasan boş','Transkript, diploma, sertifika ve diğer belgelerini ekleyebilirsin.','upload-file','Dosya ekle'))}`}
function notes(){const all=state.cache.notes||[],categories=[...new Set(all.map(x=>String(x.category||'Genel').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'tr'));let a=all.filter(x=>state.notesCategory==='all'||x.category===state.notesCategory);a.sort((x,y)=>state.notesSort==='oldest'?String(x.updated_at).localeCompare(String(y.updated_at)):String(y.updated_at).localeCompare(String(x.updated_at)));return `${titleBand('KİŞİSEL ARAŞTIRMA ALANI','Notlarım','Başvuru, danışman görüşmeleri ve araştırma fikirlerini aranabilir not kartlarında düzenle.',btn(all.length?'Not oluştur':'İlk notu oluştur','add-note','plus','btn-primary'))}<section class="premium-panel notes-panel">${blockHeading('Kayıtlı notlar', 'file',`<span class="pill">${a.length} not</span>`)}<div class="notes-toolbar list-with-filter"><label class="field"><span>Notlarda ara</span><input class="form-control" type="search" placeholder="Başlık veya içerik…" data-live-filter aria-label="Notlarda ara"/></label><label class="field"><span>Konu</span><select class="form-control" data-act="notes-category"><option value="all">Tüm konular</option>${categories.map(x=>`<option value="${attr(x)}" ${state.notesCategory===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="field"><span>Sıralama</span><select class="form-control" data-act="notes-sort"><option value="newest" ${state.notesSort==='newest'?'selected':''}>Son güncellenen</option><option value="oldest" ${state.notesSort==='oldest'?'selected':''}>İlk güncellenen</option></select></label></div><div class="notes-grid">${a.length?a.map(x=>`<article class="note-card" data-match="${attr([x.title,x.category,x.body].join(' '))}"><div class="note-heading"><h3>${esc(x.title)}</h3><span>${esc(x.category||'Genel')}</span></div><p>${esc(x.body||'')}</p><div class="note-actions"><small>${esc(x.updated_at?.slice(0,10)||'')}</small><button class="btn" data-edit="notes" data-id="${x.id}">${icon('edit',14)} Düzenle</button><button class="round-btn" data-delete="notes" data-id="${x.id}" title="Sil">${icon('trash',16)}</button></div></article>`).join(''):empty(all.length?'Bu filtrede not yok':'Henüz notun yok',all.length?'Konu filtresini değiştir veya başka bir arama yap.':'Başvuru, danışman veya araştırma fikirleri hakkında not oluştur.','add-note',all.length?'Not oluştur':'İlk notu oluştur')}</div></section>`}
function resources(){const a=state.cache.resources||[];return `${titleBand('ARAŞTIRMA KÜTÜPHANESİ','Kaynaklar & Yayınlar','Makaleleri, laboratuvar sayfalarını ve önemli bağlantıları kaydet.',btn(a.length?'Kaynak ekle':'İlk kaynağı ekle','add-resource','plus','btn-primary'))}<section class="premium-panel">${blockHeading('Kaydedilen Kaynaklar','book')}<div class="resource-grid">${a.length?a.map(x=>`<div class="resource-row"><div class="resource-icon">${icon('book',21)}</div><div><strong>${esc(x.title)}</strong><p>${esc(x.note||x.kind)}</p>${link(x.url,'Kaynağı Aç')}</div><button class="round-btn" data-edit="resources" data-id="${x.id}" title="Düzenle">${icon('edit')}</button><button class="round-btn" data-delete="resources" data-id="${x.id}" title="Sil">${icon('trash')}</button></div>`).join(''):empty('Kaynak kütüphanen boş','Doğrulanmış araştırma bağlantıları, yayınlar veya önemli sayfaları ekle.','add-resource','İlk kaynağı ekle')}</div></section>`}
function settings(){
 if(state.subpage==='settings-device')return `${sectionPageHead('Cihaz yedeği','Yedeği cihazına indir veya daha önce aldığın yedeği geri yükle.') }<section class="premium-panel">${btn('Yedek indir','backup','download','btn-primary')}<div class="helper-note margin-top">Tüm çalışma kayıtları, IELTS oturumları ve kelime defteri arşive eklenir.</div><div class="margin-top">${btn('Yedeği geri yükle','restore','upload')}</div><div class="helper-note margin-top">Geri yükleme öncesinde mevcut veriler için otomatik geri dönüş yedeği oluşturulur.</div></section>`;
 if(state.subpage==='settings-export')return `${sectionPageHead('Görevleri dışa aktar','Görevlerini başka bir uygulamada açmak için CSV olarak indir.') }<section class="premium-panel">${btn('Görev listesini indir','export-csv','download','btn-primary')}</section>`;
 if(state.subpage==='settings-drive')return `${sectionPageHead('Google Drive yedekleme','Bağlı hesabı ve otomatik yedekleme durumunu yönet.') }<section class="premium-panel"><p class="subline">Kayıtlar değiştikçe otomatik yedeklenir. Bağlantı yoksa güvenli kuyrukta bekler ve internet gelince gönderilir.</p><div id="settings-cloud-status" class="helper-note margin-top">Bulut bağlantı durumu üst çubukta görünür.</div><div class="margin-top">${btn('Google Drive bağlantısını yönet','cloud-settings','cloud','btn-primary')}</div></section>`;
 if(state.subpage==='settings-info')return `${sectionPageHead('Uygulama bilgileri','YLSY Atlas Android sürümü ve AI araçları.') }<section class="premium-panel"><h2>YLSY Atlas 4.0.0</h2><p class="muted">Güvenli yerel kayıt ve otomatik bulut yedekleme · MEB ABD başvuru rehberi: 60 sayfa.</p><div class="head-actions margin-top">${btn(state.aiStatus?.configured?'Gemini API anahtarını değiştir':'Gemini API anahtarı ekle','ai-key','key','btn-primary')}${state.aiStatus?.configured?btn('Anahtarı kaldır','ai-key-remove','trash'):''}</div><div class="helper-note margin-top">AI sözlük ve yazma koçu için Gemini kullanılır. Anahtar Android güvenli deposunda saklanır.</div></section>`;
 return `${heading('Veri güvenliği','Ayarlar ve yedekleme','Yedekleri, Drive bağlantısını ve uygulama bilgilerini ayrı girişlerden yönet.')}${sectionTiles([sectionTile('settings-device','Cihaz yedeği','Yedek indir veya geri yükle','download'),sectionTile('settings-export','Görevleri dışa aktar','Görev listesini CSV olarak indir','file'),sectionTile('settings-drive','Google Drive yedekleme','Hesap bağlantısı ve otomatik yedekleme','cloud'),sectionTile('settings-info','Uygulama bilgileri','Sürüm ve AI ayarları','info')])}`;
}

