const defaults={universities:{country:'',ylsy_status:'Doğrulanmadı',rank:99},programs:{stage:'Araştırılıyor',deadline_verified:0},advisors:{status:'Araştırılıyor'},tasks:{group_name:'Genel',track:'Kişisel',status:'todo',priority:'Normal'},documents:{kind:'Genel'},ielts_sessions:{minutes:30},vocabulary:{tags:'IELTS'},events:{kind:'Genel'}};
function refreshAtlasSelect(select){if(!select)return;const button=select.nextElementSibling;if(!button?.classList.contains('atlas-select-trigger'))return;const selected=select.selectedOptions?.[0],placeholder=select.options?.[0]?.value===''?select.options[0].textContent:'Seçiniz';button.querySelector('[data-select-label]').textContent=selected&&selected.value!==''?selected.textContent:placeholder;button.setAttribute('aria-expanded','false')}
function enhanceAndroidSelects(root=document){if(innerWidth>860)return;root.querySelectorAll('select').forEach((select,index)=>{if(select.dataset.atlasPickerBound)return;select.dataset.atlasPickerBound='true';if(!select.id)select.id='atlas-select-'+Date.now()+'-'+index;if(select.required){select.dataset.pickerRequired='true';select.required=false}select.classList.add('atlas-native-select');const button=document.createElement('button');button.type='button';button.className='guide-picker-trigger atlas-select-trigger';button.dataset.act='open-select-picker';button.dataset.selectId=select.id;button.innerHTML='<span data-select-label></span>'+icon('chevron',18);select.insertAdjacentElement('afterend',button);refreshAtlasSelect(select)})}
function openAtlasSelectPicker(id){const select=document.getElementById(id);if(!select)return;const label=document.querySelector('label[for="'+CSS.escape(id)+'"]')?.textContent?.replace(/\s*\*\s*$/,'').trim()||'Seçim yap';const options=[...select.options].filter((o,i)=>!o.disabled&&(i!==0||o.value!==''));const rows=options.map(o=>`<button type="button" class="guide-picker-option ${o.selected?'active':''}" data-act="choose-select-option" data-select-id="${attr(id)}" data-value="${attr(o.value)}" data-match="${attr(o.textContent+' '+o.value)}"><span><b>${esc(o.textContent)}</b></span>${o.selected?icon('check',18):''}</button>`).join('');const root=$('#picker-root');root.innerHTML=`<div class="modal-shade guide-picker-shade select-picker-shade" data-act="close-select-picker"><section class="modal guide-picker-modal select-picker-modal" role="dialog" aria-modal="true" aria-label="${attr(label)} seç"><header class="guide-picker-head"><h2>${esc(label)} seç</h2><button class="icon-button" data-act="close-select-picker" aria-label="Kapat">${icon('close')}</button></header><div class="guide-picker-body list-with-filter"><div class="guide-picker-search"><input class="form-control" type="search" placeholder="${attr(label)} ara…" aria-label="${attr(label)} ara" data-live-filter></div><div class="guide-picker-options">${rows}<p class="guide-picker-empty" data-filter-empty hidden>Bu aramayla eşleşen seçenek yok.</p></div></div></section></div>`}
function closeAtlasSelectPicker(){const root=$('#picker-root');if(root)root.replaceChildren()}
function chooseAtlasSelectOption(el){const select=document.getElementById(el.dataset.selectId);if(!select)return closeAtlasSelectPicker();select.value=el.dataset.value;refreshAtlasSelect(select);closeAtlasSelectPicker();select.dispatchEvent(new Event('change',{bubbles:true}))}
function taskTitleOptions(track){if(track==='Rehber')return state.guideList.map(g=>[`${g.id} · ${g.title}`,`${g.id} · ${g.title}`]);const choices={IELTS:['Listening çalışması','Reading çalışması','Writing Task 1 çalışması','Writing Task 2 çalışması','Speaking çalışması','Kelime tekrarı','Deneme sınavı'],Akademik:['Üniversite araştırması','Araştırma önerisi hazırla','Akademik CV’yi güncelle','Statement of Purpose taslağı','Referans mektubu iste','Danışmana e-posta hazırla','Literatür taraması yap'],YLSY:['MEB evraklarını kontrol et','YLSY başvuru belgelerini hazırla','Öğrenime başlama sürecini kontrol et','REBUS kaydını tamamla','MEB ile iletişime geç'],Pasaport:['Pasaport belgelerini hazırla','Pasaport randevusu al','Vize belgelerini kontrol et','DS-160 formunu tamamla','Seyahat evraklarını hazırla'],Başvuru:['Program koşullarını kontrol et','Başvuru dosyasını hazırla','Başvuru ücretini kontrol et','Başvuruyu gönder','Başvuru sonucunu takip et'],Kişisel:['Haftalık çalışma planı oluştur','Günlük hedefleri gözden geçir','Takvimi düzenle','Belgeleri arşivle']};return (choices[track]||choices.Kişisel).map(x=>[x,x])}
function taskGroupOptions(track){if(track==='Rehber'){const groups=[...new Set((state.guideList||[]).map(g=>String(g.group||'').trim()).filter(Boolean))];return ['Genel',...groups.filter(x=>x!=='Genel')]}const groups={IELTS:['Genel','Listening','Reading','Writing','Speaking','Kelime','Deneme'],Akademik:['Genel','Program araştırması','Araştırma','Akademik yazım','Danışman iletişimi','Referans'],YLSY:['Genel','Resmî evrak','REBUS','Kurum iletişimi'],Pasaport:['Genel','Pasaport','Vize','Seyahat'],Başvuru:['Genel','Üniversite araştırması','Başvuru belgeleri','Başvuru gönderimi','Sonuç takibi'],Kişisel:['Genel','Günlük plan','Haftalık hedef','Belgeler']};return groups[track]||groups.Kişisel}
function updateTaskFormTrack(track){const title=$('#form-title'),choice=$('#form-title-choice'),group=$('#form-group_name');if(!title||!choice)return;choice.innerHTML=`<option value="">Çalışma hattına göre başlık seç</option>${taskTitleOptions(track).map(([value,label])=>`<option value="${attr(value)}">${esc(label)}</option>`).join('')}<option value="__custom__">Diğer · kendi başlığımı yaz</option>`;choice.value='';title.value='';title.hidden=true;title.required=false;if(group){group.innerHTML=taskGroupOptions(track).map(value=>`<option value="${attr(value)}">${esc(value)}</option>`).join('');group.value='Genel'}refreshAtlasSelect(choice);refreshAtlasSelect(group)}
function updateTaskTitle(choice){const title=$('#form-title');if(!title)return;if(choice.value==='__custom__'){title.value='';title.hidden=false;title.required=true;title.focus()}else{title.value=choice.value;title.hidden=true;title.required=false;if($('#form-track')?.value==='Rehber'){const guide=state.guideList.find(g=>`${g.id} · ${g.title}`===choice.value),group=$('#form-group_name');if(guide&&group){group.value=guide.group||'Genel';refreshAtlasSelect(group)}}}}
function selectOptions(table,record){if(table==='universities')return (state.cache.universities||[]).map(u=>[u.id,u.name]);return (state.cache.programs||[]).filter(p=>!record?.university_id||p.university_id===Number(record.university_id)).map(p=>[p.id,`${p.university} · ${p.name}`])}
function fieldHtml(row,data,table){let [key,lbl,type,required,opts]=row,v=data[key]??'',id='form-'+key;let inner='';if(type==='task-title'){const options=taskTitleOptions(data.track||'Kişisel'),match=options.some(([value])=>String(value)===String(v)),choice=match?String(v):v?'__custom__':'';inner=`<select id="${id}-choice" data-act="task-title-choice" ${required?'required':''}><option value="">Çalışma hattına göre başlık seç</option>${options.map(([value,title])=>`<option value="${attr(value)}" ${choice===String(value)?'selected':''}>${esc(title)}</option>`).join('')}<option value="__custom__" ${choice==='__custom__'?'selected':''}>Diğer · kendi başlığımı yaz</option></select><input id="${id}" name="${key}" type="text" value="${attr(v)}" ${v&&!match?'':'hidden'} ${v&&!match&&required?'required':''} placeholder="Görev başlığını yaz"/>`}else if(type==='task-group'){const options=taskGroupOptions(data.track||'Kişisel');if(v&&!options.includes(String(v)))options.unshift(String(v));inner=`<select id="${id}" name="${key}">${options.map(option=>`<option value="${attr(option)}" ${String(v)===String(option)?'selected':''}>${esc(option)}</option>`).join('')}</select>`}else if(type==='university-search'){const u=byId('universities',v);inner=`<div class="university-picker"><input id="form-university-search" type="search" value="${attr(u?u.name:'')}" autocomplete="off" placeholder="Üniversite adını yaz · ör. MIT" aria-autocomplete="list" aria-controls="university-suggestions" aria-expanded="false"/><input type="hidden" id="${id}" name="${key}" value="${attr(v)}"/><div id="university-suggestions" class="university-suggestions" role="listbox" hidden></div></div><div id="university-preview" class="university-preview" aria-live="polite"></div>`}else if(type==='textarea')inner=`<textarea id="${id}" name="${key}" ${required?'required':''} rows="4" placeholder="${attr(lbl)}">${esc(v)}</textarea>`;else if(type==='select'||type==='universities'||type==='programs'){let options=type==='select'?opts.map(o=>Array.isArray(o)?o:[o,o]):selectOptions(type,data);inner=`<select id="${id}" name="${key}" data-act="${key==='track'?'task-track':''}" ${required?'required':''}><option value="">${type==='select'?'Se\u00e7iniz':type==='universities'?'\u00dcniversite se\u00e7iniz':type==='programs'?'Program se\u00e7iniz':'Kay\u0131t se\u00e7iniz'}</option>${options.map(([value,title])=>`<option value="${attr(value)}" ${String(v)===String(value)?'selected':''}>${esc(title)}</option>`).join('')}</select>`}else if(type==='checkbox')inner=`<label style="display:flex;gap:8px;align-items:center;color:#d6e8f5"><input type="checkbox" style="width:18px;height:18px;min-height:18px" name="${key}" id="${id}" ${Number(v)?'checked':''}/> Evet, resmî kaynaktan kontrol ettim</label>`;else inner=`<input id="${id}" name="${key}" type="${type}" value="${attr(v)}" ${type==='number'?'min="0"':''} ${required?'required':''} placeholder="${attr(lbl)}"/>`;return `<div class="field ${type==='textarea'?'span2':''} ${type==='university-search'?'university-field':''} ${type==='task-title'?'task-title-field':''}"><label for="${type==='university-search'?'form-university-search':type==='task-title'?id+'-choice':id}">${esc(lbl)} ${required?'*':''}</label>${inner}</div>`}
function renderAdvisorUniversitySuggestions(query){const root=$('#university-suggestions');if(!root)return;const q=String(query||'').trim().toLocaleLowerCase('tr-TR');let matches=(state.cache.universities||[]).filter(u=>!q||[u.name,u.short,u.city,u.country].some(x=>String(x||'').toLocaleLowerCase('tr-TR').includes(q)));matches.sort((a,b)=>{const an=String(a.name||'').toLocaleLowerCase('tr-TR'),bn=String(b.name||'').toLocaleLowerCase('tr-TR'),rank=x=>q?(x===q?0:x.startsWith(q)?1:2):0;return rank(an)-rank(bn)||an.localeCompare(bn,'tr-TR')});root.innerHTML=matches.length?matches.map(u=>'<button type="button" role="option" data-act="advisor-university-select" data-id="'+Number(u.id)+'"><strong>'+esc(u.name)+'</strong></button>').join(''):'<p class="university-suggestion-empty">'+('E\u015fle\u015fen kay\u0131t yok.\u0020\u00d6nce\u0020\u00dcniversiteler\u0020b\u00f6l\u00fcm\u00fcnden\u0020ekleyebilirsin.')+'</p>';root.hidden=false;$('#form-university-search')?.setAttribute('aria-expanded','true')}
function selectAdvisorUniversity(id){const u=byId('universities',id),hidden=$('#form-university_id'),search=$('#form-university-search'),results=$('#university-suggestions'),preview=$('#university-preview');if(!u||!hidden)return;hidden.value=u.id;search.value=u.name;results.innerHTML='';results.hidden=true;search?.setAttribute('aria-expanded','false');if(preview)preview.innerHTML='<strong>'+esc(u.name)+'</strong><span>'+esc([u.city,u.country].filter(Boolean).join(' \u00b7 ')||'Konum bilgisi kay\u0131tl\u0131 de\u011fil')+'</span><small>'+(u.url?link(u.url,'\u00dcniversitenin resm\u00ee sitesi'):'Resm\u00ee site kay\u0131tl\u0131 de\u011fil')+'</small>'}

function openAiKey(){const html='<p class="muted">AI sözlük ve yazma koçu için Google AI Studio anahtarını ekle. Anahtar Android güvenli deposunda saklanır ve Drive yedeğine eklenmez.</p><div class="field"><label for="gemini-key">API anahtarı</label><input id="gemini-key" name="key" type="password" class="form-control" autocomplete="off" placeholder="AIza…"/></div>';modal('Gemini API anahtarı',html,async f=>{state.aiStatus=await api('ai/key','POST',{key:f.elements.namedItem('key').value});render();toast('AI anahtarı güvenli biçimde kaydedildi')})}
function showCoachResult(r){const rows=(r.feedback||[]).map(x=>'<div class="related-item"><div><b>'+esc(x.original)+'</b><p>'+esc(x.improved)+'</p><small>'+esc(x.reason)+'</small></div></div>').join('');let html='<h3>'+esc(r.title)+'</h3><p>'+esc(r.summary)+'</p>'+(r.corrected_text?'<div class="helper-note"><b>Düzeltilmiş metin</b><p>'+esc(r.corrected_text)+'</p></div>':'')+(rows?'<h3>Geliştirme noktaları</h3>'+rows:'')+'<div class="helper-note margin-top"><b>Alıştırma</b><p>'+esc(r.exercise)+'</p><b>Örnek yanıt</b><p>'+esc(r.example_answer)+'</p></div>'+((r.success_criteria||[]).length?'<p><b>Ölçütler:</b> '+r.success_criteria.map(esc).join(' · ')+'</p>':'');modal('AI geri bildirimi',html)}
function openAiCoach(){const levels=['A2','B1','B2','C1','C2'].map(x=>'<option '+(x===(state.settings.cefr||'B1')?'selected':'')+'>'+x+'</option>').join('');const html='<p class="muted">Yetişkin ve akademik hedeflere uygun çalışma üretir veya yazını açıklamalı değerlendirir. Gönder düğmesine bastığında metin Google Gemini’ye iletilir.</p><div class="field"><label>Çalışma türü</label><select name="mode" class="form-control"><option value="practice">15 dakikalık çalışma hazırla</option><option value="review">Yazımı değerlendir ve düzelt</option></select></div><div class="form-grid"><div class="field"><label>Beceri</label><select name="skill" class="form-control"><option>Academic Writing</option><option>IELTS Writing</option><option>Speaking</option><option>Reading</option><option>Listening</option><option>Academic Vocabulary</option></select></div><div class="field"><label>Seviye</label><select name="level" class="form-control">'+levels+'</select></div></div><div class="field"><label>İngilizce metnin veya odak notun</label><textarea name="text" class="form-control" maxlength="10000" placeholder="Değerlendirme için yazını ekle; çalışma hazırlamak için konu veya hedef yaz."></textarea></div>';modal('İngilizce çalışma koçu',html,async f=>{const r=await api('ai/coach','POST',{mode:f.elements.namedItem('mode').value,skill:f.elements.namedItem('skill').value,level:f.elements.namedItem('level').value,text:f.elements.namedItem('text').value});setTimeout(()=>showCoachResult(r),100)},'Gemini’ye gönder')}
function modal(title,content,onSubmit=null,submitText='Kaydet'){const root=$('#modal-root');root.innerHTML=`<div class="modal-shade" data-act="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${attr(title)}"><div class="modal-top"><h2>${esc(title)}</h2><button class="icon-button" data-act="close-modal" title="Kapat">${icon('close')}</button></div><form id="modal-form"><div class="modal-content">${content}</div><div class="modal-actions"><button type="button" class="btn" data-act="close-modal">İptal</button>${onSubmit?`<button type="submit" class="btn btn-primary">${icon('save')} ${esc(submitText)}</button>`:''}</div></form></div></div>`;root._submit=onSubmit;if(onSubmit){$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();let f=e.currentTarget;let missing=f.querySelector('select[data-picker-required]');if(missing&&!missing.value){toast('Lütfen '+(document.querySelector('label[for="'+CSS.escape(missing.id)+'"]')?.textContent?.replace('*','').trim()||'bir seçim')+' seçin.',true);return}let button=f.querySelector('[type=submit]');button.disabled=true;try{await onSubmit(f);closeModal()}catch(err){toast(err.message,true)}finally{button.disabled=false}})}enhanceAndroidSelects(root);let input=root.querySelector('input:not([type=checkbox]),select');if(input&&innerWidth>860)setTimeout(()=>input.focus(),50)}
function closeModal(){$('#modal-root').replaceChildren()}
function errorMessage(e){toast(e.message||'İşlem başarısız',true)}
async function saveData(table,data,id){await api(table+(id?'/'+id:''),id?'PUT':'POST',data);await reload([table]);render();toast(id?'Değişiklik kaydedildi':'Yeni kayıt eklendi')}
function openForm(table,id=null,preset={}){let def=definitions[table];if(!def)return;let previous=id?byId(table,id):null;let d={...(defaults[table]||{}),...preset,...previous};if(table==='programs'&&!state.cache.universities.length){toast('Önce üniversite kaydı ekle',true);openForm('universities');return}if(table==='advisors'&&!state.cache.universities.length){toast('Önce üniversite kaydı ekle',true);openForm('universities');return}if(table==='ielts_sessions'&&!d.date)d.date=new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0');if(table==='events'&&!d.date)d.date=new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0');if(table==='tasks'&&preset.guide_key)d.guide_key=preset.guide_key;const html=`<div class="form-grid">${def.fields.map(x=>fieldHtml(x,d,table)).join('')}</div>${table==='programs'?'<div class="helper-note">Son başvuru tarihi ayrıca doğrulandığını işaretlemeden kesin kabul edilmez.</div>':''}${table==='vocabulary'?'<div id="dictionary-hint" class="helper-note span2">Kelimeyi yazınca anlam ve örnek cümleler aranır. Sonucu gözden geçirip kaydedebilirsin.</div>':''}`;
 modal((id?'Düzenle: ':'Yeni ')+def.title,html,async f=>{let out={};for(let [key,lbl,type,required]of def.fields){let el=f.elements.namedItem(key);if(!el)continue;let v=type==='checkbox'?(el.checked?1:0):el.value.trim();if(required&&!v)throw new Error(lbl+' boş olamaz');out[key]=v}if(table==='documents'&&!id){out.html=String(preset.html||'');if(preset.ref_key)out.ref_key=preset.ref_key}if(table==='tasks'&&preset.guide_key){out.guide_key=preset.guide_key;out.source_page=preset.source_page||0}let saved=await api(table+(id?'/'+id:''),id?'PUT':'POST',out);await reload([table]);if(table==='documents'){state.docId=saved.id;state.nav='documents'}render();toast('Kaydedildi')});
  const u=$('#form-university_id'),search=$('#form-university-search');if(table==='advisors'&&u&&search){const chosen=byId('universities',u.value);if(chosen)selectAdvisorUniversity(chosen.id);search.addEventListener('input',()=>{u.value='';$('#university-preview').innerHTML='<span>Üniversite seçilince şehir, ülke ve resmî site burada gösterilir.</span>';renderAdvisorUniversitySuggestions(search.value)});search.addEventListener('focus',()=>renderAdvisorUniversitySuggestions(search.value));search.addEventListener('keydown',e=>{if(e.key==='Enter'&&!u.value){const first=$('#university-suggestions [data-act="advisor-university-select"]');if(first){e.preventDefault();selectAdvisorUniversity(first.dataset.id)}}})}}
async function deleteRecord(table,id){let entry=byId(table,id);let text=entry?.name||entry?.title||entry?.word||entry?.original_name||'bu kayıt';let extra=table==='universities'?' Bu üniversiteye bağlı bütün programlar ve danışmanlar da silinir.':'';if(!confirm('“'+text+'” kalıcı olarak silinsin mi?'+extra))return;try{if(table==='documents'){clearTimeout(state.docTimer);state.docTimer=null;}if(table==='vocabulary')state.vocabQuiz=null;await api(table+'/'+id,'DELETE');if(table==='documents'&&state.docId===Number(id))state.docId=null;await reload(table==='universities'?['universities','programs','advisors']:table==='programs'?['programs','advisors']:[table]);render();toast('Kayıt silindi')}catch(e){errorMessage(e)}}
function cleanHtml(source){const el=document.createElement('template');el.innerHTML=String(source||'');const whitelist=new Set(['H1','H2','H3','H4','P','BR','DIV','SPAN','STRONG','B','EM','I','U','UL','OL','LI','BLOCKQUOTE','HR','A']);function sanitize(node){for(const c of [...node.childNodes]){if(c.nodeType===1){if(!whitelist.has(c.tagName)){let text=document.createTextNode(c.textContent||'');c.replaceWith(text);continue}let href=c.tagName==='A'?c.getAttribute('href'):null;for(const a of [...c.attributes])c.removeAttribute(a.name);if(href&&/^https?:\/\//i.test(href))c.setAttribute('href',href);sanitize(c)}else if(c.nodeType!==3)c.remove()}}sanitize(el.content);return el.innerHTML}
async function saveDocument(){let editor=$('#doc-editor');if(!editor)return;let id=Number(editor.dataset.documentId);if(!id)return;let html=cleanHtml(editor.innerHTML);let indicator=$('#save-indicator');if(indicator)indicator.textContent='Kaydediliyor…';try{await api('documents/'+id,'PUT',{html});let docs=state.cache.documents||[],d=docs.find(x=>x.id===+id);if(d)d.html=html;if(indicator&&$('#doc-editor')===editor)indicator.textContent='Kaydedildi'}catch(e){if(indicator&&$('#doc-editor')===editor)indicator.textContent='Kayıt başarısız';errorMessage(e)}}
function chooseTemplate(){let templates=state.templates;modal('Belge şablonu seç',`<div class="list-rows">${templates.map((t,i)=>`<button type="button" class="list-row" data-act="create-template" data-index="${i}" style="width:100%;text-align:left;cursor:pointer"><span class="list-icon">${icon('file')}</span><span class="list-row-main"><strong>${esc(t.title)}</strong><small>Rehber ${esc(t.ref_key)} · PDF sayfa ${t.page} · Yeni kişisel belge oluştur</small></span>${icon('right')}</button>`).join('')}</div>`,null)}
