function saveFile(name,blob){if(window.AndroidAtlas?.saveFile){let reader=new FileReader();reader.onload=()=>{try{AndroidAtlas.saveFile(name,String(reader.result).split(',').pop(),blob.type||'application/octet-stream')}catch(e){toast('Dosya dışa aktarılamadı',true)}};reader.onerror=()=>toast('Dosya okunamadı',true);reader.readAsDataURL(blob);return}let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),9000)}
async function download(endpoint,name){try{let response=await fetch('/api/'+endpoint,{headers:{'X-Atlas-Token':TOKEN}});if(!response.ok)throw new Error('Dosya alınamadı');saveFile(name,await response.blob());toast('Dosya hazırlandı')}catch(e){errorMessage(e)}}
async function uploadFile(file){if(!file)return;if(file.size>20*1024*1024){toast('En fazla 20 MB dosya yükleyebilirsin',true);return}let bytes=await file.arrayBuffer(),array=new Uint8Array(bytes),parts=[];for(let i=0;i<array.length;i+=8192)parts.push(String.fromCharCode(...array.subarray(i,i+8192)));let base64=btoa(parts.join(''));try{await api('attachments','POST',{name:file.name,mime:file.type||'application/octet-stream',owner_type:'general',owner_id:0,content:base64});await reload(['attachments','notes','resources']);render();toast('Dosya eklendi')}catch(e){errorMessage(e)}}
async function restoreBackup(file){if(!file)return;if(!confirm('Yedek geri yüklenecek; mevcut veriler yedeklenerek değiştirilecek. Devam edilsin mi?'))return;let buf=await file.arrayBuffer(),a=new Uint8Array(buf),s=[];for(let i=0;i<a.length;i+=8192)s.push(String.fromCharCode(...a.subarray(i,i+8192)));try{await api('restore','POST',{content:btoa(s.join(''))});await reload(['universities','programs','advisors','tasks','documents','ielts_sessions','vocabulary','events','attachments','notes','resources']);state.docId=null;render();toast('Yedek başarıyla geri yüklendi')}catch(e){errorMessage(e)}}
