async function importGuidePdf(file){
 if(!file)return;
 if(file.size>40*1024*1024||file.size<100){toast('PDF dosyası 40 MB altında olmalıdır.',true);return}
 const bytes=new Uint8Array(await file.arrayBuffer());
 if(new TextDecoder().decode(bytes.subarray(0,5))!=='%PDF-'){toast('Geçerli bir PDF dosyası seçmelisin.',true);return}
 const chunks=[];for(let i=0;i<bytes.length;i+=8192)chunks.push(String.fromCharCode(...bytes.subarray(i,i+8192)));
 try{toast('PDF uygulamaya ekleniyor…');await api('guide-pdf/import','POST',{content:btoa(chunks.join(''))});state.guidePdf=await api('guide-pdf/status');render();toast('MEB rehberi kaydedildi ve görüntüleyiciye eklendi.')}
 catch(e){errorMessage(e)}
}
